gqy(){return"\u0ba4\u0bcb\u0bb2\u0bcd\u0bb5\u0bbf"},
gyg(){return"\u0baa\u0b9e\u0bcd\u0b9a\u0bcd \u0b87\u0ba9\u0bcd"},
